def nxt(t):
    import re
    m=re.match(r'([A-Z])([A-Z])(\d+)',t)
    return m.group(1),m.group(2),int(m.group(3))
s=['AH21','CJ18','EL15','GN12']
a,b,n=nxt(s[-1])
ans=chr(ord(a)+2)+chr(ord(b)+2)+str(n-3)
opts={'A':'HR11','B':'IP9','C':'J8','D':'HQ10'}
assert ans==opts['B']
for k in 'ACD': assert ans!=opts[k]

from fractions import Fraction as F
v={'a':F(480),'b':F(3,10),'c':F(5),'d':F(500),'f':F(190),'g':F(9),'h':F(27),'i':F(16,10)}
def e(a,b,c,d,f,g,h,i): return (a/b*c+d)/(f+g*h/i)
opts={'A':(F(5),F(9)),'B':(F(3,10),F(16,10)),'C':(F(27),F(480)),'D':(F(500),F(190))}
ok=[]
for k,(x,y) in opts.items():
    w={n:(y if val==x else x if val==y else val) for n,val in v.items()}
    if e(**w)==2: ok.append(k)
assert ok==['B']

